const storage={get(k,f){try{return localStorage.getItem('luke-acts-'+k)||f}catch{return f}},set(k,v){try{localStorage.setItem('luke-acts-'+k,v)}catch{}}};
const shapes={map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16',leaf:'M4 20C1 10 9 3 21 3c0 12-7 20-17 17ZM4 20 16 8',book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3ZM12 6v15',words:'M4 6h16M4 12h11M4 18h7M18 10l3 3-3 3M21 13h-6',concepts:'M9 18h6M10 21h4M8 14a7 7 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',comment:'M4 4h16v13H9l-5 4ZM8 8h8M8 12h5',link:'M10 14l4-4M8 16l-1 1a4 4 0 0 1-5-5l4-4a4 4 0 0 1 5 0M16 8l1-1a4 4 0 0 1 5 5l-4 4a4 4 0 0 1-5 0',lock:'M5 10h14v11H5ZM8 10V7a4 4 0 0 1 8 0v3M12 14v3'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${shapes[n]||shapes.book}"/></svg>`;
const legacyViews={words:'tools',concepts:'story'};
const navs=[['introduction','Introduction','Intro','leaf'],['reading','Read the text','Read','book'],['studies','Weekly studies','Studies','map'],['commentaries','Pastoral Commentaries','Comments','comment'],['story','The Story So Far','Story','concepts'],['tools','Bible Study Tools','Tools','words'],['resources','External Resources','Resources','link']];
let curriculum,bible,passages,catalog,reflections,journey,weeklyStudy,approvedStories,storyPromise,referencePromise,modalVersion=0;
let completed=[],progressSaved=true,lastGateSignature='',releaseTimer;
const state={view:'introduction',week:Math.min(12,Math.max(1,Number(storage.get('week',1))||1)),rhythm:storage.get('rhythm','weekly'),scope:'week',category:'keywords',word:null,verse:null,context:true,tool:'words',size:Math.min(25,Math.max(16,Number(storage.get('size',20))||20)),module:'all',glossaryTheme:'current',glossaryQuery:''};
if(!['weekly','fortnightly'].includes(state.rhythm))state.rhythm='weekly';
document.documentElement.classList.toggle('dark',storage.get('theme','light')==='dark');
function theme(){const dark=document.documentElement.classList.contains('dark');$('#theme').textContent=dark?'☀':'☾';$('#theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} mode`)}
theme();$('#theme').onclick=()=>{document.documentElement.classList.toggle('dark');storage.set('theme',document.documentElement.classList.contains('dark')?'dark':'light');theme()};
document.documentElement.style.setProperty('--reading-size',state.size+'px');
const weekLabel=s=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',timeZone:'Europe/Paris'}).format(new Date(s.length===10?s+'T12:00:00Z':s))+' Week';
const moduleWeeks=id=>{const weeks=curriculum.sessions.filter(s=>s.module===id);return weeks.length===1?weekLabel(weeks[0].date):weekLabel(weeks[0].date)+' – '+weekLabel(weeks.at(-1).date);};
const session=()=>curriculum.sessions[state.week-1];
function currentGroup(){return groupSessions(curriculum.sessions,state.rhythm).find(g=>g.some(s=>s.number===state.week));}
function heading(n,title,copy,tag=''){return `<div class="section-head"><div class="section-title"><span class="step">${n}</span><div><h2>${title}</h2><p>${copy}</p></div></div>${tag?`<span class="tag">${tag}</span>`:''}</div>`;}
function nav(){ $('#navigation').innerHTML=navs.map(([id,label,short,shape],i)=>`<a class="nav-item ${state.view===id?'active':''}" href="#${id}" ${state.view===id?'aria-current="page"':''} aria-label="${label}">${icon(shape)}<span class="nav-text"><span class="desktop-label">${label}</span><span class="mobile-label">${short}</span></span><small>0${i+1}</small></a>`).join('');}
function go(view,scroll=true){view=legacyViews[view]||view;state.view=navs.some(n=>n[0]===view)?view:'introduction';history.replaceState(null,'','#'+state.view);nav();render();$('#view .study-panel').classList.add('view-enter');if(scroll)$('#view').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&navs.some(n=>a.hash==='#'+n[0])){e.preventDefault();go(a.hash.slice(1));}});
window.addEventListener('hashchange',()=>go(location.hash.slice(1),false));
function pickWeek(n){state.week=Number(n);state.word=null;state.verse=null;state.context=true;storage.set('week',state.week);}
function studySelector(){const groups=groupSessions(curriculum.sessions,state.rhythm);const index=groups.findIndex(g=>g.some(s=>s.number===state.week));return `<div class="study-selector"><div class="selector-fields"><label for="rhythm">Meeting rhythm<select id="rhythm"><option value="weekly" ${state.rhythm==='weekly'?'selected':''}>Every week</option><option value="fortnightly" ${state.rhythm==='fortnightly'?'selected':''}>Every two weeks</option></select></label><label for="week">${state.rhythm==='weekly'?'Study week':'Two-week gathering'}<select id="week">${groups.map((g,i)=>`<option value="${g[0].number}" ${i===index?'selected':''}>${g.map(s=>weekLabel(s.date)).join(' + ')} · ${g.length===1?g[0].passage:'Weeks '+g[0].number+' & '+g[1].number}</option>`).join('')}</select></label></div><div class="week-arrows"><button class="icon-button" data-week="${groups[index-1]?.[0].number||1}" ${index===0?'disabled':''} aria-label="Previous study">←</button><button class="icon-button" data-week="${groups[index+1]?.[0].number||12}" ${index===groups.length-1?'disabled':''} aria-label="Next study">→</button></div></div>${state.rhythm==='fortnightly'?'<p class="rhythm-note">Use the same three prompts for both passages. Carry the second week’s bridge question into your next gathering.</p>':''}`;}
function pastoralIntro(){return `<section class="pastoral-intro" aria-labelledby="pastoral-welcome"><div class="eyebrow">GROWING TOGETHER IN THE WORD</div><h3 id="pastoral-welcome">${esc(pastoralIntroduction.title)}</h3><p class="pastoral-welcome">${esc(pastoralIntroduction.welcome)}</p><p class="pastoral-credit">Read, observe, interpret and apply each passage. At the end of a module, The Story So Far brings the scenes together around the question that has guided us.</p></section>`;}
function intro(){return heading('01','The King has come','One story, twelve weeks, and room to grow together.','ACT I')+`<div class="welcome-copy"><p>${esc(curriculum.welcome)}</p><div class="series-facts"><span><strong>12</strong> weekly studies</span><span><strong>3</strong> modules + an interlude</span><span><strong>1</strong> connected story</span></div></div>${pastoralIntro()}<div class="section-subhead"><h3>Your journey through Act I</h3><span>October – December 2026</span></div><div class="module-grid">${curriculum.modules.slice(0,3).map(m=>`<article class="module-card">${moduleArt(m)}<div class="module-body"><div class="eyebrow">MODULE ${m.id} · ${esc(moduleWeeks(m.id))}</div><h3>${esc(m.name)}</h3><p class="big-question">${esc(artAvailable(curriculum.sessions.find(s=>s.module===m.id))?m.question:openingLabel(curriculum.sessions.find(s=>s.module===m.id)))}</p><p>${esc(m.description)}</p></div></article>`).join('')}</div><div class="interlude"><span class="step">12</span><div><div class="eyebrow">28 DECEMBER WEEK · INTERLUDE</div><h3>Thirty Years Later…</h3><p>${esc(curriculum.modules[3].description)}</p></div></div><section class="method-section"><h3>How we study together</h3><p>Begin with the Bible, listen carefully to one another, and let each scene lead the conversation.</p><div class="method-grid">${weeklyStudy.method.map((m,i)=>`<article><small>0${i+1}</small><h4>${m.title}</h4><p>${esc(m.question)}</p></article>`).join('')}</div></section><div class="two-rhythms"><h3>One study plan. Two ways to meet.</h3><p>If your group meets every week, follow one passage and its questions. If you meet every two weeks, bring the two most recent studies together, using the same three discussion prompts. Everyone follows the same story, and the second Narrative Bridge carries a fortnightly group into its next gathering.</p><p class="annotation">Begin in Read the text and choose your study week.</p></div>${future()}`;}
function future(){return `<div class="future-act">${icon('lock')}<div><span class="eyebrow">CONTINUING IN 2027</span><h3>Act II · The King begins his ministry</h3><p>Our journey will continue towards Jerusalem, the cross, the resurrection and the witness of the church. These later studies are not open yet; their dates and teaching will be announced.</p></div><span class="tag">LOCKED</span></div>`;}
function highlighted(text){if(!state.word)return esc(text);const forms=[...state.word.forms].sort((a,b)=>b.length-a.length).map(f=>f.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const re=new RegExp(`\\b(${forms.join('|')})(?:[’']s)?\\b`,'gi');let output='',last=0;for(const match of text.matchAll(re)){output+=esc(text.slice(last,match.index))+`<mark>${esc(match[0])}</mark>`;last=match.index+match[0].length;}return output+esc(text.slice(last));}
function chapter(s){return bible.chapters[s.book+'.'+s.chapter];}
function readVerses(s){return state.context?Object.entries(chapter(s).verses).map(([verse,text])=>({verse:Number(verse),text,key:`${s.book}.${s.chapter}.${verse}`})):s.verses;}
function reading(){
 return heading('02','Read the text','Read the whole chapter, with this week’s passage highlighted. Let the text lead the conversation.','WEB')+studySelector()+currentGroup().map(s=>{
  const m=curriculum.modules.find(m=>m.id===s.module),c=chapter(s);
  const verses=Object.entries(c.verses).map(([n,text])=>{const v=Number(n),focus=v>=s.start&&v<=s.end,key=`${s.book}.${s.chapter}.${v}`;let copy=highlighted(text);
   if(s.partialEnd&&v===s.end){const excerpt=s.verses.at(-1).text;copy=`<span class="study-verse-part">${highlighted(excerpt)}</span><span class="context-remainder">${highlighted(text.slice(excerpt.length))}</span>`;}
   return `${v===s.start?`<div class="passage-start" id="study-start-${s.number}" tabindex="-1"><span class="eyebrow">THIS WEEK’S PASSAGE · ${esc(s.passage)}</span></div>`:''}<p id="verse-${s.number}-${v}" tabindex="-1" class="verse ${focus?'focus-verse':'context-verse'} ${s.partialEnd&&v===s.end?'partial-verse':''}"><span class="verse-num" aria-label="Verse ${v}">${v}</span>${copy}</p>`;
  }).join('');
  return `<article class="reading-session"><header class="reading-session-head"><span class="eyebrow">${weekLabel(s.date)} · ${moduleLabel(s.module).toUpperCase()}</span><h3>${esc(sessionTitle(s))}</h3></header>${sessionArt(s)}<div class="paper chapter-paper"><div class="reader-toolbar"><div><strong>${esc(c.book)} ${s.chapter} · Complete chapter</strong><p class="annotation">The burgundy edge marks ${esc(s.passage)}. The surrounding verses remain visible for context.</p><button class="text-link" data-study-jump="${s.number}">Jump to the study passage ↓</button></div><div class="type-tools"><button data-size="-1" aria-label="Smaller Bible text">A−</button><button data-size="1" aria-label="Larger Bible text">A+</button></div></div>${state.word?`<div class="selected-info"><span>Highlighting <strong>${esc(state.word.word)}</strong></span><button data-clear>Clear ×</button></div>`:''}<div class="reading-text">${verses}</div><div class="scripture-credit">World English Bible Classic · Public domain. Scripture wording is unchanged. ${s.partialEnd?'The study highlights only the opening clause of Micah 5:5; the rest of the verse remains visible.':''}</div></div>${sceneConnections(s)}<section class="reading-discussion"><h3>Explore this scene together</h3>${questions(s)}</section><div class="reading-next">${s.number!==currentGroup().at(-1).number?'':s.number<12?`<button class="secondary-button" data-read="${s.number+1}">Continue to ${weekLabel(curriculum.sessions[s.number].date)} →</button>`:'<a class="secondary-button" href="#story">Return to The Story So Far →</a>'}</div></article>`;
 }).join('');
}
function verseLabel(key){const [b,c,v]=key.split('.');return `${bible.chapters[b+'.'+c]?.book||({'2Sam':'2 Samuel',Isa:'Isaiah',Mic:'Micah'}[b]||b)} ${c}:${v}`;}
const bookNames={Gen:'Genesis',Exod:'Exodus',Lev:'Leviticus',Num:'Numbers',Deut:'Deuteronomy',Josh:'Joshua',Judg:'Judges','1Sam':'1 Samuel','2Sam':'2 Samuel','1Kgs':'1 Kings','2Kgs':'2 Kings','1Chr':'1 Chronicles','2Chr':'2 Chronicles',Neh:'Nehemiah',Ps:'Psalms',Prov:'Proverbs',Eccl:'Ecclesiastes',Song:'Song of Solomon',Isa:'Isaiah',Jer:'Jeremiah',Lam:'Lamentations',Ezek:'Ezekiel',Dan:'Daniel',Hos:'Hosea',Obad:'Obadiah',Mic:'Micah',Nah:'Nahum',Hab:'Habakkuk',Zeph:'Zephaniah',Hag:'Haggai',Zech:'Zechariah',Mal:'Malachi',Matt:'Matthew',Rom:'Romans','1Cor':'1 Corinthians','2Cor':'2 Corinthians',Gal:'Galatians',Eph:'Ephesians',Phil:'Philippians',Col:'Colossians','1Thess':'1 Thessalonians','2Thess':'2 Thessalonians','1Tim':'1 Timothy','2Tim':'2 Timothy',Phlm:'Philemon',Heb:'Hebrews',Jas:'James','1Pet':'1 Peter','2Pet':'2 Peter','1John':'1 John','2John':'2 John','3John':'3 John',Rev:'Revelation'};
function refLabel(key){if(passages?.[key])return passages[key].label;const [a,b]=key.split('-');const [book,c,v]=a.split('.');const end=b?.split('.');return `${bookNames[book]||book} ${c}:${v}${b?'–'+(end[1]===c?end[2]:end[1]+':'+end[2]):''}`;}
function scopeSessions(){if(state.scope==='all')return curriculum.sessions;if(state.scope.startsWith('module-'))return curriculum.sessions.filter(s=>s.module===Number(state.scope.split('-')[1]));return currentGroup();}
function analysisVerses(){return scopeSessions().flatMap(s=>s.verses.map(v=>({...v,week:s.number,label:chapter(s).book+' '+s.chapter+':'+v.verse+(v.part||'')})));}

function words(){const verses=analysisVerses(),list=analyze(verses,state.category);let word=state.word?list.find(w=>w.word===state.word.word):list[0];state.word=word||null;const max=list[0]?.count||1;return '<h3 class="tool-heading">Repeated words</h3><p class="info-note">Select a word to explore its meaning in the study passage.</p>'+studySelector()+`<div class="analysis-controls"><label for="scope">Explore repetitions in<select id="scope"><option value="week" ${state.scope==='week'?'selected':''}>This ${state.rhythm==='weekly'?'week':'gathering'}</option>${curriculum.modules.map(m=>`<option value="module-${m.id}" ${state.scope==='module-'+m.id?'selected':''}>${m.id===4?'Interlude':'Module '+m.id} · ${esc(m.name)}</option>`).join('')}<option value="all" ${state.scope==='all'?'selected':''}>All of Act I · 12 passages</option></select></label><div class="tabs" aria-label="Word category"><button data-category="keywords" class="${state.category==='keywords'?'active':''}" aria-pressed="${state.category==='keywords'}">Key words</button><button data-category="actions" class="${state.category==='actions'?'active':''}" aria-pressed="${state.category==='actions'}">Action words</button></div></div><p class="info-note">Select a word to explore it. Larger capsules appear more often. Related English forms are counted together; common linking words are left out of the key-word list.</p><div class="paper word-cloud">${list.slice(0,50).map(w=>{const ratio=w.count/max,tier=ratio>=.8?5:ratio>=.5?4:ratio>=.3?3:ratio>=.2?2:1;return `<button class="word-cloud-pill frequency-${tier} ${word?.word===w.word?'active':''}" data-word="${esc(w.word)}" aria-pressed="${word?.word===w.word}" aria-label="${esc(w.word)}, ${w.count} occurrences"><span>${esc(w.word)}</span><b>${w.count}</b></button>`}).join('')||'<p>No repeated words in this category. Try a wider selection.</p>'}</div>${list.length>50?'<p class="annotation">Showing the 50 most frequent terms in this selection.</p>':''}${word?`<section class="word-insight" id="word-insight"><span class="eyebrow">WORD INSIGHT</span><h3>${esc(word.word)}</h3><div class="word-meaning">${paragraphs(word.definition)}</div></section>`:''}`;}
const moduleLabel=id=>id===4?'Interlude':'Module '+id;
const moduleState=id=>{const source=reflections?.modules.find(m=>m.id===id),full=approvedStories?.modules.find(m=>m.id===id);return {...source,...(full?.reading?full:{}),id,releaseAt:journey.storyDates[id],released:Date.now()>=Date.parse(journey.storyDates[id]),available:storyAvailable(id)};};
const currentModule=()=>[...curriculum.sessions].reverse().find(s=>Date.now()>=Date.parse(lessonMeta(s)?.releaseAt))?.module||1;
const glossaryModule=g=>curriculum.sessions[g.week-1].module;
async function openModuleReading(id,sectionId){
 if(!storyAvailable(id))return;
 try{await ensureStories()}catch{showToast('The reading could not be loaded. Please try again.');return}
 const module=moduleState(id),reading=module?.reading,topic=selectStoryTopic(reading,sectionId);
 if(!module?.available||!topic)return;
 const blocks=topic.blocks.map(b=>b.kind==='quote'?`<blockquote class="module-scripture"><cite>${esc(b.reference)}</cite>${paragraphs(b.text)}</blockquote>`:b.kind==='heading'?`<h4>${esc(b.text)}</h4>`:paragraphs(b.text)).join('');
 openDialog(`ACT I / STORY / ${moduleLabel(id).toUpperCase()}`,topic.title,
 `<div class="module-reading-meta">${topic.wordCount.toLocaleString('en-GB')} words · About ${topic.minutes} minutes</div><div class="module-reading-content"><section class="module-reading-section"><img src="./assets/${topic.image}" alt="${esc(topic.alt)}" width="1774" height="887">${blocks}</section></div><p class="pastoral-credit">${esc(reading.credit)}</p><p class="reading-return-note">Close this reading to return to the same place in ${esc(moduleLabel(id))}.</p>`);
}
function openConcept(index){const card=concepts[index];if(card)openModuleReading(card.module,'theme-'+index);}
function filterGlossary(){
 const q=state.glossaryQuery.trim().toLowerCase(),active=state.glossaryTheme==='current'?currentModule():Number(state.glossaryTheme);
 const found=glossary.filter(g=>(state.glossaryTheme==='all'||glossaryModule(g)===active)&&(g.word+' '+g.forms.join(' ')+' '+g.definition).toLowerCase().includes(q));
 $('#glossary-list').innerHTML=found.map(glossaryItem).join('')||'<p class="annotation">No matching terms. Try a different word, or choose Browse all terms.</p>';
 $('#glossary-status').textContent=`${found.length} of ${glossary.length} terms${state.glossaryTheme==='current'?' · '+moduleLabel(active):''}`;
 $('#glossary-list').querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.read);go('reading')});
}
function jumpToGlossary(word){closeDialog();state.tool='glossary';state.glossaryTheme='all';state.glossaryQuery=word;go('tools',false);$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});const match=[...$('#glossary-list').querySelectorAll('details')].find(el=>el.querySelector('summary span').textContent===word);if(match)match.open=true;}
function moduleReflections(m){
 const available=moduleState(m.id),cards=concepts.map((c,index)=>({...c,index})).filter(c=>c.module===m.id),ready=available.available,done=moduleCompleted(m.id,curriculum.sessions,completed),total=curriculum.sessions.filter(s=>s.module===m.id).length,count=curriculum.sessions.filter(s=>s.module===m.id&&completed.includes(s.number)).length;
 return `<section class="reflection-module ${ready?'is-open':'is-locked'}" aria-labelledby="reflection-module-${m.id}"><header class="reflection-module-head"><div><span class="eyebrow">${moduleLabel(m.id).toUpperCase()} · ${esc(moduleWeeks(m.id))}</span><h3 id="reflection-module-${m.id}">${esc(m.name)}</h3></div><span class="module-status">${ready?'':icon('lock')}${done?'Module completed':ready?'Open for reflection':'Read the scenes first'}</span></header><div class="guiding-question"><span class="eyebrow">THE QUESTION THAT CONNECTS THIS MODULE</span><p>${esc(artAvailable(curriculum.sessions.find(s=>s.module===m.id))?m.question:openingLabel(curriculum.sessions.find(s=>s.module===m.id)))}</p></div><p class="module-release">${count} of ${total} sessions completed. ${journey.storyUnlock==='completion-only'?'Complete every session to open this reflection.':`Opens when you complete this module, or in ${weekLabel(available.releaseAt)}.`}</p>${ready?`<p class="topic-invitation">Choose one theme to read. Each opens on its own, and closes back here.</p><div class="concept-grid">${cards.map(c=>`<button type="button" class="concept-card journey-frame ${done?'is-complete':''}" data-concept="${c.index}" aria-label="Read ${esc(c.title)}"><img class="theme-image" src="./assets/${c.image}" alt="${esc(c.alt)}" loading="lazy"><span class="concept-copy"><span class="eyebrow">${esc(c.reference)}</span><span class="concept-title">${esc(c.title)}</span></span></button>`).join('')}</div>`:`${lockedCover()}<p class="annotation">Finish the module’s studies, then return here to reflect on how the scenes fit together.</p>`}</section>`;
}
function conceptsView(){return heading('05','The Story So Far','Pause at the end of a module and see how its scenes belong to one story.','3 MODULES + INTERLUDE')+progressSummary()+`<p class="info-note">These readings bring together the themes you have explored. They open after you complete the module${journey.storyUnlock==='completion-only'?'':', or when its study period has finished'}. The Bible readings, questions and study tools are always available.</p><nav class="module-jump" aria-label="Jump to a story module">${curriculum.modules.map(m=>`<button class="word-pill" data-module-jump="${m.id}">${moduleLabel(m.id)}</button>`).join('')}</nav>${curriculum.modules.map(moduleReflections).join('')}`;}
function glossaryView(){return `<section class="pastoral-glossary" aria-labelledby="glossary-heading"><div class="glossary-head"><div><h3 id="glossary-heading">A glossary for the journey</h3><p>${glossary.length} words and ideas, explained in everyday English. All definitions are available from the beginning.</p></div></div><div class="glossary-tools"><label for="glossary-search">Find a word or an idea<input id="glossary-search" type="search" placeholder="For example: grace, promise, incarnation…" value="${esc(state.glossaryQuery)}"></label><label for="glossary-theme">Explore by module<select id="glossary-theme"><option value="current" ${state.glossaryTheme==='current'?'selected':''}>Current module · ${moduleLabel(currentModule())}</option><option value="all" ${state.glossaryTheme==='all'?'selected':''}>Browse all terms</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${state.glossaryTheme===String(m.id)?'selected':''}>${moduleLabel(m.id)} · ${esc(m.name)}</option>`).join('')}</select></label></div><p class="annotation">Before the first opening, Current module shows Module 1. These definitions help us read; they are not additional words counted in the Bible text.</p><p id="glossary-status" class="glossary-count" role="status"></p><div id="glossary-list" class="glossary-list"></div></section>`;}

function glossaryItem(g){return `<details class="glossary-item"><summary><span>${esc(g.word)}</span><b aria-hidden="true">+</b></summary><div class="definition"><p>${esc(g.definition)}</p><p class="glossary-context">Explore alongside ${esc(g.reference)}</p></div></details>`;}
function methodCards(){return `<div class="question-set">${weeklyStudy.method.map((m,i)=>`<section class="study-question"><span class="question-label">0${i+1} · ${esc(m.title)}</span><p>${esc(m.question)}</p></section>`).join('')}</div>`;}
function questions(s){if(!artAvailable(s))return methodCards()+`<section class="narrative-bridge"><span class="eyebrow">ONE QUESTION TO CARRY FORWARD</span><p>${esc(openingLabel(s))}. Return then for this week’s question.</p></section>`;return methodCards()+`<section class="narrative-bridge"><span class="eyebrow">ONE QUESTION TO CARRY FORWARD</span><p>${esc(weeklyStudy.sessions[s.number-1].bridgeQuestion)}</p><p class="bridge-invitation">${esc(weeklyStudy.discussionNote)}</p></section>`;}
function lessonMeta(s){return catalog?.lessons?.find(l=>l.id===s.id)}
function statusCard(s){const l=lessonMeta(s);if(l?.status==='available')return `<div class="commentary-ready"><span>Pastoral commentary is available</span><button class="primary-button" data-lesson="${s.id}">Read commentary ↗</button></div>`;return `<div class="awaiting-commentary">${icon('lock')}<div><strong>${l?.status==='scheduled'?'Commentary scheduled':'Waiting for content from Pastors'}</strong><p>For ${weekLabel(s.date)}. ${l?.status==='scheduled'?'Available during this study week.':'The reading and discussion guide are ready in Read the text. The commentary will appear when the pastors have supplied it and this study week has begun.'}</p></div></div>`;}
function studiesView(){const group=currentGroup();return heading('03','Weekly studies','Read the passage, discuss the questions, and carry the story into your week.')+studySelector()+progressSummary()+`<div class="curriculum-note"><p>Begin each week in Read the text. Return here to mark a study as completed and follow your progress.</p></div>${group.map(s=>`<article class="session-guide"><header><span class="eyebrow">${weekLabel(s.date)} · ${s.module===4?'INTERLUDE':'MODULE '+s.module}</span><h3>${esc(sessionTitle(s))}</h3><button class="text-link" data-read="${s.number}">${esc(s.passage)} · Read the text ↗</button></header>${sessionArt(s)}${completionControl(s)}${artAvailable(s)&&s.leaderNote?`<details class="leader-note"><summary>For group leaders <b>+</b></summary><p>${esc(s.leaderNote)}</p></details>`:''}</article>`).join('')}<section class="all-studies"><div class="section-subhead"><h3>All twelve weeks</h3><label for="module-filter" class="sr-only">Filter study weeks by module</label><select id="module-filter"><option value="all">All modules</option>${curriculum.modules.map(m=>`<option value="${m.id}" ${state.module===String(m.id)?'selected':''}>${m.id===4?'Interlude':'Module '+m.id}</option>`).join('')}</select></div><div class="schedule-list">${curriculum.sessions.filter(s=>state.module==='all'||s.module===Number(state.module)).map(s=>`<button class="schedule-item ${group.some(g=>g.number===s.number)?'current':''}" data-study="${s.number}">${sessionArt(s,true)}<span class="schedule-date">${weekLabel(s.date)}</span><span><strong>${esc(sessionTitle(s))}</strong><small>${esc(s.passage)}</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div></section>${future()}`;}
function resourcesView(){return heading('07','External Resources','Choose the tool that helps with the question you are asking.','11 TOOLS')+`<section class="resource-intro"><h3>Start with Scripture. Then explore.</h3><p>These links bring together the tools from both pages of the D-Groups Bible Study Resources guide. Use them after reading the passage for yourself, and bring questions that remain to your group.</p></section>${['Historical setting','Study the passage','Places and words'].map((category,i)=>`<section class="resource-section"><h3>${category}</h3><div class="resource-grid">${resources.filter(r=>r[2]===category).map(([name,url,,copy])=>`<a class="resource-card" href="${url}" target="_blank" rel="noopener noreferrer"><h4 class="resource-brand">${esc(name.split(' · ')[0])}${name.includes(' · ')?`<span class="resource-service">${esc(name.split(' · ')[1])}</span>`:''}</h4><p>${copy}</p><small>${new URL(url).hostname}</small><span class="text-link">Open resource ↗</span></a>`).join('')}</div></section>`).join('')}<section class="method-section"><h3>A simple guide for your time together</h3><p>Adapted from the D-Groups study method: observe, interpret, apply, encourage one another and pray.</p>${[...weeklyStudy.method.map(m=>[m.title,m.question]),...methodGuide.slice(3)].map(([title,copy],i)=>`<details class="method-detail"><summary><span>0${i+1} · ${title}</span><b>+</b></summary><p>${copy}</p></details>`).join('')}</section>`;}
function pastoralCommentariesView(){
 const s=session();
 return heading('04','Pastoral Commentaries','Teaching from our pastors, one study week at a time.')+`<div class="study-selector commentary-selector"><label for="week">Commentary week<select id="week">${curriculum.sessions.map(w=>`<option value="${w.number}" ${w.number===s.number?'selected':''}>${weekLabel(w.date)} · ${esc(w.passage)}</option>`).join('')}</select></label><div class="week-arrows"><button class="icon-button" data-week="${s.number-1}" ${s.number===1?'disabled':''} aria-label="Previous commentary week">←</button><button class="icon-button" data-week="${s.number+1}" ${s.number===12?'disabled':''} aria-label="Next commentary week">→</button></div></div><article class="session-guide pastoral-week"><header><span class="eyebrow">${weekLabel(s.date)} · ${moduleLabel(s.module)}</span><h3>${esc(artAvailable(s)?(lessonMeta(s)?.title||s.title):openingLabel(s))}</h3><p>${esc(s.passage)}</p></header>${statusCard(s)}</article><p class="annotation">Weekly teaching and its illustrations will be added as the pastors prepare each commentary. There is no commentary to read until its content is published.</p>`;
}
function render(){if(!curriculum)return;updateLocation();$('#view').innerHTML=`<div class="study-panel">${sectionBanner()}${({introduction:intro,reading,tools:toolsView,story:conceptsView,studies:studiesView,commentaries:pastoralCommentariesView,resources:resourcesView}[state.view])()}</div>`;wire();wireFrames($('#view'));lastGateSignature=gateSignature();scheduleWeekOpening();}
function openDialog(kicker,title,body){modalVersion++;$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}`;if(!$('#detail').open){document.documentElement.classList.add('dialog-open');$('#detail').showModal();}$('#detail').scrollTop=0;return modalVersion;}
function closeDialog(){modalVersion++;$('#detail').close();document.documentElement.classList.remove('dialog-open');}
$('#detail').addEventListener('close',()=>document.documentElement.classList.remove('dialog-open'));
$('#close-dialog').onclick=closeDialog;$('#detail').addEventListener('cancel',()=>modalVersion++);
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});

async function loadReferences(){if(passages)return passages;if(!referencePromise)referencePromise=fetchJSON('./references.json').then(data=>passages=data).catch(e=>{referencePromise=null;throw e});return referencePromise;}
async function openReference(ref){const version=openDialog('WORLD ENGLISH BIBLE',refLabel(ref),'<p role="status">Opening the connected passage…</p>');try{await loadReferences();if(version!==modalVersion||!$('#detail').open)return;const p=passages[ref];if(!p)throw Error('Missing reference');$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(p.label)}</h2>${p.verses.map(v=>`<p class="scripture-quote"><sup>${v.chapter}:${v.verse}</sup>${esc(v.text)}</p>`).join('')}<p>Read the surrounding chapter before deciding how the passages connect.</p><a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Read the chapter at eBible.org ↗</a>`;wireModal();}catch{if(version===modalVersion)$('#dialog-body').innerHTML=`<h2 id="dialog-title">Unable to load this passage</h2><p>Please check your connection and try again.</p><button class="primary-button" data-ref="${ref}">Try again</button>`;wireModal();}}
function guide(n){const s=curriculum.sessions[n-1];openDialog(`${weekLabel(s.date)}`,sessionTitle(s),`<p>${esc(s.passage)}</p>${questions(s)}<button class="primary-button" data-study="${s.number}">Open the study page</button>`);wireModal();}
async function openLesson(id){const l=catalog.lessons.find(l=>l.id===id);if(l?.status!=='available')return;const version=openDialog('PASTORAL COMMENTARY',l.title,'<p role="status">Opening commentary…</p>');try{const data=await fetchJSON(`${$('meta[name="lesson-base"]').content}/${encodeURIComponent(id)}/lesson.json`,{cache:'no-store'});if(version!==modalVersion||!$('#detail').open)return;$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(data.title)}</h2>${paragraphs(data.introduction)}${data.points.map((p,i)=>`<section><h3>${i+1}. ${esc(p.title)}</h3><div class="point-reference">${esc(p.reference)}</div>${p.image?`<img src="${$('meta[name="lesson-base"]').content}/${id}/${encodeURIComponent(p.image)}" alt="${esc(p.alt)}" loading="lazy">`:''}${paragraphs(p.text)}</section>`).join('')}<h3>A final word</h3>${paragraphs(data.finalWord)}<p class="annotation">Teaching supplied by the pastors of EIC Paris.</p>`;}catch{if(version===modalVersion)$('#dialog-body').innerHTML='<h2 id="dialog-title">Commentary unavailable</h2><p>Please try again later. The teaching may not yet be available for this study week.</p>';}}
function wireModal(){ $('#dialog-body').querySelectorAll('[data-glossary-jump]').forEach(b=>b.onclick=()=>jumpToGlossary(b.dataset.glossaryJump)); $('#dialog-body').querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));$('#dialog-body').querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.study);go('studies')});$('#dialog-body').querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{closeDialog();pickWeek(b.dataset.read);go('reading')});}
function wire(){
 document.querySelectorAll('[data-module-jump]').forEach(b=>b.onclick=()=>$('#reflection-module-'+b.dataset.moduleJump).scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'}));
 $('[data-glossary-all]')?.addEventListener('click',()=>{state.glossaryTheme='all';state.glossaryQuery='';render();$('#glossary-search').focus({preventScroll:true});$('#glossary-heading').scrollIntoView({block:'start'})});
 $('#week')?.addEventListener('change',e=>{pickWeek(e.target.value);render();$('#week').focus({preventScroll:true})});
 $('#rhythm')?.addEventListener('change',e=>{state.rhythm=e.target.value;storage.set('rhythm',state.rhythm);state.word=null;state.verse=null;render();$('#rhythm').focus({preventScroll:true})});
 document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.week);render()});
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.read);go('reading')});
 document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.study);go('studies')});
 document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{const m=Number(b.dataset.module);pickWeek(curriculum.sessions.find(s=>s.module===m).number);state.module=String(m);go('studies')});
 $('[data-open-classes]')?.addEventListener('click',()=>go('studies'));
 $('#context')?.addEventListener('change',e=>{state.context=e.target.checked;render();$('#context').focus()});
 document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.size=Math.min(25,Math.max(16,state.size+Number(b.dataset.size)));storage.set('size',state.size);document.documentElement.style.setProperty('--reading-size',state.size+'px')});

 document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>openReference(b.dataset.ref));
 document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>guide(Number(b.dataset.guide)));
 $('[data-clear]')?.addEventListener('click',()=>{state.word=null;render()});
 $('#scope')?.addEventListener('change',e=>{state.scope=e.target.value;state.word=null;render();$('#scope').focus({preventScroll:true})});
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.word=null;render();$(`[data-category="${state.category}"]`).focus()});
 document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{state.word=analyze(analysisVerses(),state.category).find(w=>w.word===b.dataset.word);render();$(`[data-word="${state.word.word}"]`)?.focus({preventScroll:true});$('#word-insight').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})});
 document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>{const [week,verse]=b.dataset.hit.split(':').map(Number);const word=state.word;pickWeek(week);state.word=word;state.rhythm='weekly';storage.set('rhythm','weekly');state.verse=`${session().book}.${session().chapter}.${verse}`;go('reading',false);requestAnimationFrame(()=>{$(`#verse-${week}-${verse}`)?.scrollIntoView({block:'center'});$(`#verse-${week}-${verse}`)?.focus({preventScroll:true})})});
 document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>openConcept(Number(b.dataset.concept)));
 wireJourney();
 if($('#glossary-list'))filterGlossary();
 $('#glossary-search')?.addEventListener('input',e=>{state.glossaryQuery=e.target.value;filterGlossary()});
 $('#glossary-theme')?.addEventListener('change',e=>{state.glossaryTheme=e.target.value;filterGlossary()});
 document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));
 $('#module-filter')?.addEventListener('change',e=>{state.module=e.target.value;render();$('#module-filter').focus({preventScroll:true})});
}
$('#sources').onclick=()=>openDialog('D-GROUPS · ABOUT','Growing together in the Word.',`<section class="about-credits"><h3>Pastoral team</h3><p><strong>EIC Rueil-Malmaison:</strong><br>Jeff Walters — Senior Pastor<br>Christian Nartatez — Associate Pastor</p><p><strong>EIC Rive Gauche:</strong><br>John Hugh — Senior Pastor</p><h3>Developed by</h3><p>The Graphic Department at EIC Paris</p><h3>With thanks to</h3><p>Anabel B. &amp; Nicky DeFitte</p></section><h3>Scripture</h3><p>The <a href="https://ebible.org/eng-web/" target="_blank" rel="noopener noreferrer">World English Bible Classic</a> is in the public domain. This app contains the twelve Act I readings and their seven surrounding chapters. Scripture is reproduced from the official eBible archive, without editorial headings or footnote markers. Micah 5:5a is an excerpt; its full verse is available in chapter context.</p><h3>Supporting scenes</h3><p>Each study includes two selected WEB passages to help explore the module question and the final Narrative Bridge. These passages use the existing Scripture imports without rewriting them. The short hints on the cards are editorial reading aids; participants can follow other observations and applications that arise from the texts.</p><h3>TSK-based cross references</h3><p>The <a href="https://www.openbible.info/labs/cross-references/" target="_blank" rel="noopener noreferrer">OpenBible.info dataset</a> draws primarily on the Treasury of Scripture Knowledge and includes additional connections. The imported source includes 3,333 rows for the seven context chapters, with 2,733 distinct WEB passages. TSK Bible Concordance displays six selected connections from each weekly study passage. Each connection keeps its source verse and adds a brief editorial explanation; these explanations were not supplied by TSK. The dataset is used under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>, with an editorial selection for the twelve study passages. A cross reference is a starting point for comparison, not proof that two passages have identical meanings.</p><h3>Curriculum and resources</h3><p>The twelve passages, narrative journey and module introductions come from EIC Paris’s “DGroups Curriculum Framework: From Bethlehem to the Nations, Act I”, dated October–December 2026. The three brief discussion prompts are adapted from the observation, interpretation and application sections of the D-Groups 1 Peter guide. Its 2025 dates and readings do not apply to this series. One condensed Narrative Bridge question is kept for each week. Resource links come from both pages of the Bible Study Resources guide.</p><h3>Study notes and pastoral teaching</h3><p>The study notes, teaching texts and pastoral commentaries are developed by Associate Pastor Christian Nartatez at EIC Rueil-Malmaison, under the supervision of the Senior Pastors of EIC Paris.</p><h3>Illustrations and design</h3><p>The Low Poly illustrations with cel-style shading were generated with AI as symbolic illustrations, not archaeological reconstructions. The design follows the D-Groups and EIC Paris study apps.</p><h3>Your preferences</h3><p>Completed studies, meeting rhythm, selected week, theme and reading size stay in this browser. Progress is not synced between devices; clearing browser site data removes it. If storage is unavailable, completion lasts only for the current visit. Review-edition progress is kept separate. Each week’s title, illustration, narrative question and completion button open on Monday at 06:00 Paris time. Completion cannot reveal a future week. Module reflections open after the module is completed or its study period has ended. They do not change the pastoral commentary release calendar. This app does not collect names or shared notes. Act II and later teaching are not included.</p>`);
async function fetchJSON(url,options){const r=await fetch(url,options);if(!r.ok)throw Error(`${r.status}`);return r.json();}
async function loadReflections(){
 const url=$('meta[name="reflection-catalog"]').content;
 const next=await fetchJSON(url,{cache:'no-store'});
 reflections=next;
}
async function refreshReleases(){
 if(!curriculum)return;
 const before=JSON.stringify(reflections),beforeCatalog=JSON.stringify(catalog);
 try{await loadReflections();catalog=await fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'});if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();if(!$('#detail').open&&(before!==JSON.stringify(reflections)||beforeCatalog!==JSON.stringify(catalog)||lastGateSignature!==gateSignature()))render()}catch{/* Keep the last verified view; a reload retries the request. */}
}
window.addEventListener('focus',refreshReleases);
setInterval(()=>{if(!document.hidden)refreshReleases()},60000);
async function start(){try{[curriculum,bible,catalog,journey,weeklyStudy]=await Promise.all([fetchJSON('./curriculum.json'),fetchJSON('./data.json'),fetchJSON($('meta[name="lesson-catalog"]').content,{cache:'no-store'}),fetchJSON('./journey.json'),fetchJSON('./weekly-study.json',{cache:'no-store'})]);await loadReflections();completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))await ensureStories();go(location.hash.slice(1)||'introduction',false);}catch{$('#view').innerHTML='<div class="error"><h2>The study could not be opened</h2><p>Please check your connection, then reload the page.</p><button id="retry" class="primary-button">Try again</button></div>';$('#retry').onclick=start}}
start();


function progressKey(){return reflections?.review?'review-progress-v1':'progress-v1';}
function readProgress(){try{const key='luke-acts-'+progressKey(),raw=localStorage.getItem(key),saved=parseProgress(raw),valid=eligibleProgress(saved,catalog.lessons);if(valid.length!==saved.length)localStorage.setItem(key,JSON.stringify({version:1,completed:valid}));progressSaved=true;return valid;}catch{progressSaved=false;return [];}}
function storyAvailable(id){return storyOpen(id,curriculum.sessions,completed,journey.storyDates[id],Date.now(),false,journey.storyUnlock);}
function artAvailable(s){return weekOpen(lessonMeta(s)?.releaseAt);}
function openingLabel(s){return 'Opens the week of '+weekLabel(s.date).replace(' Week','');}
function sessionTitle(s){return artAvailable(s)?s.title:openingLabel(s);}
function scheduleWeekOpening(){clearTimeout(releaseTimer);const next=catalog.lessons.map(l=>Date.parse(l.releaseAt)).filter(t=>t>Date.now()).sort((a,b)=>a-b)[0];if(next)releaseTimer=setTimeout(()=>{if(!$('#detail').open)render();refreshReleases();},Math.min(next-Date.now()+20,2147483647));}
function gateSignature(){return JSON.stringify([curriculum.sessions.map(artAvailable),curriculum.modules.map(m=>storyAvailable(m.id))]);}
function showToast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function lockedCover(compact=false){return `<span class="series-cover ${compact?'compact-cover':''}"><img src="./assets/series-mosaic.webp" alt="${compact?'':esc(journey.seriesCover.alt)}" width="1774" height="887" loading="lazy"><span class="series-wordmark"><span class="series-lock">${icon('lock')}</span><strong>From Bethlehem<br>to the Nations</strong><small>D-GROUP BIBLE STUDY SERIES</small></span></span>`;}
function sessionArt(s,compact=false){const item=journey.sessions[s.number-1],open=artAvailable(s),done=open&&completed.includes(s.number);return `<span class="session-art journey-frame ${done?'is-complete':''} ${compact?'session-thumb':''}" data-session-art="${s.number}">${open?`<img src="./assets/${item.image}?v=20261009" alt="${compact?'':esc(item.alt)}" width="1774" height="887" loading="lazy">`:lockedCover(compact)}${done?'<span class="completed-badge">✓ Completed</span>':!open&&!compact?`<span class="art-unlock">${esc(openingLabel(s))} · Monday, 06:00 Paris time.</span>`:''}</span>`;}
function moduleArt(m){const c=concepts.find(c=>c.module===m.id);return storyAvailable(m.id)?`<img src="./assets/${c.image}" alt="${esc(c.alt)}" width="1774" height="887" loading="lazy">`:lockedCover();}
function progressSummary(){return `<section class="journey-progress" aria-label="Your Act I progress"><div><strong>Your journey · ${completed.length} of 12 studies completed</strong><p>${reflections?.review?'Review progress is separate. ':''}${progressSaved?'Saved in this browser on this device. Clearing site data removes it; it does not sync to other devices.':'Browser storage is unavailable. Your progress will last only for this visit.'}</p></div><progress max="12" value="${completed.length}" aria-label="Completed studies">${completed.length} of 12</progress></section>`;}
function completionControl(s){if(!artAvailable(s))return `<section class="completion-control" aria-label="Week ${s.number} completion"><div><strong>${esc(openingLabel(s))}</strong><p>Available from Monday at 06:00 Paris time.</p></div><button class="primary-button" disabled aria-disabled="true">Mark week ${s.number} as completed</button></section>`;const done=completed.includes(s.number),ready=storyAvailable(s.module);return `<section class="completion-control" aria-label="Week ${s.number} completion"><div><strong>${done?'✓ Study completed':'Finished this study?'}</strong><p>After reading, observation, interpretation, application and prayer, mark your study here.</p></div><button class="${done?'secondary':'primary'}-button" data-complete="${s.number}" aria-pressed="${done}">${done?'Mark week '+s.number+' as not completed':'Mark week '+s.number+' as completed'}</button>${ready?`<a class="text-link" href="#story">Return to The Story So Far ↗</a>`:''}</section>`;}
function sceneConnections(s){const item=journey.sessions[s.number-1],hints=weeklyStudy.sessions[s.number-1].hints;return `<section class="scene-connections" aria-labelledby="scene-${s.number}"><span class="eyebrow">A LITTLE MORE CONTEXT</span><h4 id="scene-${s.number}">Two passages to explore</h4><div class="support-card-grid">${item.connections.map((p,i)=>`<article class="support-card"><button class="text-link" data-scene="${s.number}:${i}">Look at ${esc(p.reference)} ↗</button><p>${esc(hints[i])}</p></article>`).join('')}</div></section>`;}
function openScene(number,index){const s=journey.sessions[number-1],p=s?.connections[index];if(!p)return;openDialog('SUPPORTING PASSAGE · WEB',p.reference,`<p class="connection-hint">${esc(weeklyStudy.sessions[number-1].hints[index])}</p>${p.verses.map(v=>`<p class="scripture-quote"><sup>${v.verse}</sup>${esc(v.text)}</p>`).join('')}<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Read the surrounding chapter ↗</a>`);}

async function ensureStories(){
 if(approvedStories)return approvedStories;
 if(reflections?.review){approvedStories=reflections;return approvedStories;}
 if(!storyPromise)storyPromise=fetchJSON($('meta[name="story-catalog"]').content,{cache:'no-store'}).then(data=>{approvedStories=data;return data}).catch(e=>{storyPromise=null;throw e});
 return storyPromise;
}
function tskView(){return `<h3 class="tool-heading">TSK Bible Concordance</h3><p class="info-note">Six selected connections for each study passage. Follow a word, a shared image or an earlier promise. The short notes are reading hints, not quotations from TSK.</p>${studySelector()}${currentGroup().map(s=>`<section class="weekly-concordance"><header><span class="eyebrow">${weekLabel(s.date)}</span><h4>${esc(s.passage)}</h4><button class="text-link" data-read="${s.number}">Return to this week’s reading ↗</button></header><div class="concordance-grid">${weeklyStudy.sessions[s.number-1].concordance.map((c,i)=>`<article class="concordance-card"><span class="connection-origin">From ${esc(verseLabel(c.source)+(c.source==='Mic.5.5'?'a':''))}</span><button class="text-link" data-connection="${s.number}:${i}">${esc(refLabel(c.ref))} ↗</button><p>${esc(c.reason)}</p></article>`).join('')}</div></section>`).join('')}`;}
async function openConnection(number,index){const c=weeklyStudy.sessions[number-1]?.concordance[index];if(!c)return;await openReference(c.ref);if($('#detail').open&&$('#dialog-title')?.textContent===refLabel(c.ref)){const note=document.createElement('p');note.className='connection-hint';note.textContent=verseLabel(c.source)+(c.source==='Mic.5.5'?'a':'')+' → '+refLabel(c.ref)+'. '+c.reason;$('#dialog-title').after(note);}}

function toolsView(){const names={words:'Repeated words',glossary:'Glossary',tsk:'TSK Bible Concordance'};return heading('06','Bible Study Tools','Follow a word, understand an idea, or compare related passages.')+`<div class="tool-tabs" role="tablist" aria-label="Bible study tools">${Object.entries(names).map(([key,name])=>`<button role="tab" id="tool-tab-${key}" aria-controls="tool-panel" aria-selected="${state.tool===key}" tabindex="${state.tool===key?0:-1}" data-tool="${key}">${name}</button>`).join('')}</div><section id="tool-panel" role="tabpanel" aria-labelledby="tool-tab-${state.tool}">${({words,glossary:glossaryView,tsk:tskView}[state.tool])()}</section>`;}
function wireJourney(){
 document.querySelectorAll('[data-study-jump]').forEach(b=>b.onclick=()=>$('#study-start-'+b.dataset.studyJump)?.focus());
 document.querySelectorAll('[data-tools-tsk]').forEach(b=>b.onclick=()=>{pickWeek(b.dataset.toolsTsk);state.tool='tsk';go('tools');});
 document.querySelectorAll('[data-tool]').forEach(b=>{b.onclick=()=>{state.tool=b.dataset.tool;render();$('#tool-tab-'+state.tool).focus();};b.onkeydown=e=>{const keys=['words','glossary','tsk'],i=keys.indexOf(state.tool);let next;if(e.key==='ArrowRight')next=keys[(i+1)%3];if(e.key==='ArrowLeft')next=keys[(i+2)%3];if(e.key==='Home')next=keys[0];if(e.key==='End')next=keys[2];if(next){e.preventDefault();state.tool=next;render();$('#tool-tab-'+next).focus();}};});
 document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>openScene(...b.dataset.scene.split(':').map(Number)));
 document.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>openConnection(...b.dataset.connection.split(':').map(Number)));
 document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=async()=>{
  const n=Number(b.dataset.complete);if(!artAvailable(curriculum.sessions[n-1])){render();return;}const wasDone=completed.includes(n);completed=toggleCompleted(completed,n,lessonMeta(curriculum.sessions[n-1])?.releaseAt);
  try{localStorage.setItem('luke-acts-'+progressKey(),JSON.stringify({version:1,completed}));progressSaved=true;}catch{progressSaved=false;}
  if(curriculum.modules.some(m=>storyAvailable(m.id))){try{await ensureStories()}catch{/* Completion stays saved. Opening the reading offers a retry. */}}
  render();document.querySelector(`[data-complete="${n}"]`)?.focus({preventScroll:true});
  showToast(!progressSaved?'Completed for this visit; browser storage is unavailable.':wasDone?'Completion removed.':moduleCompleted(curriculum.sessions[n-1].module,curriculum.sessions,completed)?'Module completed. The Story So Far is open.':'Study completed. Your scene is now open.');
 });
}
window.addEventListener('storage',async e=>{if(curriculum&&e.key==='luke-acts-'+progressKey()){completed=readProgress();if(curriculum.modules.some(m=>storyAvailable(m.id)))try{await ensureStories()}catch{}if(!$('#detail').open)render();}});

const sectionScenes={introduction:['intro','Introduction','Enter the story.'],reading:['read','Read','Listen to the text.'],studies:['studies','Studies','One week at a time.'],commentaries:['commentaries','Commentaries','Pastoral teaching for each study week.'],story:['story','Story','See the threads come together.'],tools:['tools','Tools','Look closer at the words.'],resources:['resources','Resources','Explore a little further.']};
function sectionBanner(){const [id,title,copy]=sectionScenes[state.view];return `<div class="section-banner" aria-label="${title}">${id?`<img src="./assets/banner-${id}.webp" alt="" width="1536" height="512" decoding="async">`:""}<div><span class="eyebrow">FROM BETHLEHEM TO THE NATIONS · ACT I</span><p class="banner-title">${title}</p><p>${copy}</p></div></div><div class="location-trail" aria-label="Your place in the study">Act I <span aria-hidden="true">/</span> ${esc(navs.find(n=>n[0]===state.view)[1])}${['reading','studies','commentaries'].includes(state.view)?` <span aria-hidden="true">/</span> ${esc(weekLabel(session().date))}`:state.view==='tools'?` <span aria-hidden="true">/</span> ${esc({words:'Repeated words',glossary:'Glossary',tsk:'TSK Bible Concordance'}[state.tool])}`:''}</div>`;}
function updateLocation(){const label=navs.find(n=>n[0]===state.view)[2];$('.breadcrumb').innerHTML=`<span class="crumb-series">Luke–Acts / Act I</span><strong aria-current="page">${esc(label)}</strong>`;}
